Use grade-school multiplication, accumulating digits right to left with carry, then remove leading zeros.

```javascript
function solve(a, b) {
  const m = a.length;
  const n = b.length;
  const digits = new Array(m + n).fill(0);

  for (let i = m - 1; i >= 0; i--) {
    const x = a.charCodeAt(i) - 48;
    let carry = 0;

    for (let j = n - 1; j >= 0; j--) {
      const y = b.charCodeAt(j) - 48;
      const sum = x * y + digits[i + j + 1] + carry;
      digits[i + j + 1] = sum % 10;
      carry = Math.floor(sum / 10);
    }

    digits[i] = carry;
  }

  let start = 0;
  while (start < digits.length - 1 && digits[start] === 0) {
    start++;
  }
  return digits.slice(start).join('');
}
```

Time: O(a.length × b.length). Space: O(a.length + b.length). Handles leading zeros and returns exactly "0" for any zero product, without BigInt or whole-input numeric conversion.

