Check exactly four strict decimal groups for IPv4, or exactly eight strict hexadecimal groups for IPv6. Reject whitespace, mixed separators, empty groups, and IPv6 shorthand.

```javascript
function solve(address) {
  const v4 = address.split('.');
  if (v4.length === 4 && v4.every(group =>
    group.length >= 1 &&
    group.length <= 3 &&
    !/[^0-9]/.test(group) &&
    (group.length === 1 || group[0] !== '0') &&
    Number(group) <= 255
  )) {
    return 'IPv4';
  }

  const v6 = address.split(':');
  if (v6.length === 8 && v6.every(group =>
    group.length >= 1 &&
    group.length <= 4 &&
    !/[^0-9a-fA-F]/.test(group)
  )) {
    return 'IPv6';
  }

  return 'Neither';
}
```

Call `solve(address)` directly with a string; no imports, exports, or stdin/stdout are needed. Time: O(n); auxiliary space: O(n) for splitting, where n is the address length.

